def trans_vertical(P,axis_c, source='bottom',H=18,W=18):
 ax=[(r,c) for r,c in P if c==axis_c]; sides=[(r,c) for r,c in P if c!=axis_c]
 if not sides:return set(P)
 dr=(-min(r for r,c in P) if source=='top' else H-1-max(r for r,c in P))
 res=set(ax)
 for side,left in [( [(r,c) for r,c in sides if c<axis_c],True), ([(r,c) for r,c in sides if c>axis_c],False)]:
  if not side:continue
  dc=-min(c for r,c in side) if left else W-1-max(c for r,c in side)
  res|={(r+dr,c+dc) for r,c in side}
 return res
def trans_horizontal(P,axis_r,source='right',H=18,W=18):
 ax=[(r,c) for r,c in P if r==axis_r]; sides=[(r,c) for r,c in P if r!=axis_r]
 if not sides:return set(P)
 dc=(-min(c for r,c in P) if source=='left' else W-1-max(c for r,c in P))
 res=set(ax)
 for side,top in [([(r,c) for r,c in sides if r<axis_r],True), ([(r,c) for r,c in sides if r>axis_r],False)]:
  if not side: continue
  dr=-min(r for r,c in side) if top else H-1-max(r for r,c in side)
  res|={(r+dr,c+dc) for r,c in side}
 return res
